        /// <summary>The Uptime cell: "34 min" here and "not restarted for 31 days" in Health are two different clocks
        /// — the tooltip says which is which (a PC that hibernates was turned on 34 min ago, Windows was restarted 31 days ago).</summary>
        private void SetUptimeCell(string uptimeText)
        {
            if (FindName("TxtUptimeV") is not TextBlock up2) return;
            up2.Text = uptimeText;
            try
            {
                var kernel = SMDWin.Services.PowerOnClock.KernelUptime;
                up2.ToolTip = SMDWin.Services.PowerOnClock.KernelKeptRunning
                    ? PT("Since the PC was turned on or woke from hibernation: {0} · since Windows was last restarted: {1}", uptimeText, SMDWin.Services.DisplayFormat.Uptime(kernel))
                    : PT("Since the PC was turned on: {0}", uptimeText);
            }
            catch (Exception ex) { AppLogger.Debug($"Uptime tooltip: {ex.Message}"); }
        }

