        private async void SpeedDialStorageBench_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                await NavigateTo("Disk");
                await System.Threading.Tasks.Task.Delay(300);
                await Dispatcher.InvokeAsync(() =>
                {
                    if (_fullBenchCts == null) RunFullBench_Click(sender, e);   // a run in progress keeps going
                }, System.Windows.Threading.DispatcherPriority.Background);
            }
            catch (Exception ex)
            {
                AppLogger.Warning(ex, "SpeedDialStorageBench_Click");
                ShowToastError(string.Format(LanguageService.S("Msg", "StorageBenchFailFmt"), ex.Message));
            }
        }

