        // ── DASHBOARD LOAD ────────────────────────────────────────────────────
        private async Task LoadDashboardAsync()
        {
            // Restart background ping if it was stopped when we left Dashboard
            if (!_pingRunning && (_dashPingCts == null || _dashPingCts.IsCancellationRequested))
                StartDashboardBackgroundPing();

            // ── TTL: skip expensive WMI re-fetch if data is still fresh ───────
            bool summaryStale = (DateTime.Now - _summaryLoadedAt) > _summaryTtl;

            if (!summaryStale && _dashPopulatedOnce && !string.IsNullOrEmpty(_summary?.OsName))
            {
                RefreshDashCheapDynamics();
                HideLoading();
                return;
            }

            // ── Step 1: show whatever we already have instantly (no overlay) ──
            if (_summary != null && !string.IsNullOrEmpty(_summary.OsName))
            {
                PopulateDashboardFromSummary(_summary);
                _dashPopulatedOnce = true;
            }

            if (!summaryStale && !string.IsNullOrEmpty(_summary?.OsName))
            {
                HideLoading();
                return;
            }

            bool haveSomethingToShow = _summary != null && !string.IsNullOrEmpty(_summary.OsName);
            if (!haveSomethingToShow) ShowLoading(_LS("Dashboard", "RefreshingInfo"));
            var __dashSw = System.Diagnostics.Stopwatch.StartNew();
            void __DashLap(string label)
            {
                if (__dashSw.ElapsedMilliseconds > 300)
                    AppLogger.Warning($"S97-DIAG LoadDashboardAsync: {label} took {__dashSw.ElapsedMilliseconds}ms");
                __dashSw.Restart();
            }
            try
            {
                SystemSummary fresh;
                try   { fresh = await _hwService.GetSystemSummaryAsync(); }
                catch (OperationCanceledException)
                {
                    if (!haveSomethingToShow && TxtOs != null) TxtOs.Text = LanguageService.S("WindowsInfo", "InfoTimedOut");
                    fresh = _summary ?? new SystemSummary();
                }
                __DashLap("GetSystemSummaryAsync");
                _summary = fresh;
                _summaryLoadedAt = DateTime.Now;
                // the slow WMI queries (updates, TPM, license, key) run in the background FIRST; Populate uses only the cache
                // 1) what is already known is shown immediately; 2) then the rest is filled in (license, TPM, last update) as it arrives
                bool slowCached = _cachedLastUpdateText != null && _cachedTpmText != null && _cachedLicenseText != null && _cachedWinProductKey != null;
                if (!slowCached)
                {
                    _dashSlowPending = true;
                    try { PopulateDashboardFromSummary(_summary); } finally { _dashSlowPending = false; }
                    _dashPopulatedOnce = true;
                    __DashLap("PopulateDashboardFromSummary (without the slow data)");
                    // license / TPM / last update (WMI, up to ~5 s on laptops) no longer keep the window hidden: their rows are filled in
                    // as they arrive
                    _ = CompleteDashboardSlowDataAsync();
                }
                else
                {
                    PopulateDashboardFromSummary(_summary);
                    _dashPopulatedOnce = true;
                    __DashLap("PopulateDashboardFromSummary");
                }

                // Disk info — fast, local
                try
                {
                    var di = new System.IO.DriveInfo("C");
                    if (di.IsReady)
                    {
                        double freeGB  = di.AvailableFreeSpace / 1_073_741_824.0;
                        double totalGB = di.TotalSize           / 1_073_741_824.0;
                        double pct     = (totalGB - freeGB) / totalGB * 100;
                        if (TxtDashDiskMain != null) TxtDashDiskMain.Text = $"{pct:F0}%";
                        if (TxtDashDiskSub  != null) TxtDashDiskSub.Text  = T4($"{freeGB:F1} GB free  /  {totalGB:F0} GB total", $"{freeGB:F1} GB liberi  /  {totalGB:F0} GB în total", $"{freeGB:F1} GB frei  /  {totalGB:F0} GB gesamt", $"{freeGB:F1} Go libres  /  {totalGB:F0} Go au total");
                        if (DashDiskBar != null)
                            DashDiskBar.Width = Math.Max(0,
                                DashDiskBar.MaxWidth > 0 ? DashDiskBar.MaxWidth * pct / 100.0 : pct);
                    }
                }
                catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.LoadDashboardAsync"); }
                __DashLap("DriveInfo C: (local, no WMI)");

                // Disk models — heavier, load after UI is already shown
                if (_allDisks.Count == 0)
                {
                    if (!haveSomethingToShow) TxtLoadingMsg.Text = _LS("Disk", "LoadingModels");
                    try { _allDisks = await _hwService.GetDisksAsync(); }
                    catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.LoadDashboardAsync"); }
                    __DashLap("GetDisksAsync (_allDisks was empty)");
                }
                await PopulateDashboardHardwareRowAsync(_summary);
                __DashLap("PopulateDashboardHardwareRowAsync");
                await PopulateDashStorageGridAsync();
                __DashLap("PopulateDashStorageGridAsync");
                UpdateHealthScore();
                __DashLap("UpdateHealthScore");
            }
            finally { if (!haveSomethingToShow) HideLoading(); }
        }

        private bool _dashPopulatedOnce = false;

        private void RefreshDashCheapDynamics()
        {
            try
            {
                // Uptime — time since the PC was switched on (PowerOnClock: Fast Startup does not reset Windows' own counter)
                var up = SMDWin.Services.PowerOnClock.SinceOn;
                string uptimeText = SMDWin.Services.DisplayFormat.Uptime(up);
                SetUptimeCell(uptimeText);
                if (TxtUptime != null) TxtUptime.Text = uptimeText;
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try
            {
                var di = new System.IO.DriveInfo("C");
                if (di.IsReady)
                {
                    double freeGB  = di.AvailableFreeSpace / 1_073_741_824.0;
                    double totalGB = di.TotalSize           / 1_073_741_824.0;
                    double pct     = (totalGB - freeGB) / totalGB * 100;
                    if (TxtDashDiskMain != null) TxtDashDiskMain.Text = $"{pct:F0}%";
                    if (TxtDashDiskSub  != null) TxtDashDiskSub.Text  = T4($"{freeGB:F1} GB free  /  {totalGB:F0} GB total", $"{freeGB:F1} GB liberi  /  {totalGB:F0} GB în total", $"{freeGB:F1} GB frei  /  {totalGB:F0} GB gesamt", $"{freeGB:F1} Go libres  /  {totalGB:F0} Go au total");
                }
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
            // The charts: the same forced redraw as in Populate (the canvases were Collapsed while on another page — ActualWidth
            // may be 0 on the first layout pass, hence the Dispatcher at Loaded priority).
            Dispatcher.InvokeAsync(() =>
            {
                _dashSizeChanged = true;
                try { if (_qCpuTemp.Count >= 2) DrawDashTempChart(DashCpuTempChart, _cCpuTemp ?? _arrCpuTemp, _penDashCpuTemp, SettingsService.Current.ChartShowFill); } catch (Exception ex2) { AppLogger.Debug(ex2.Message); }
                try { if (_qGpuTemp.Count >= 2) DrawDashTempChart(DashGpuTempChart, _cGpuTemp ?? _arrGpuTemp, _penDashGpuTemp, SettingsService.Current.ChartShowFill); } catch (Exception ex2) { AppLogger.Debug(ex2.Message); }
                try { if (_qDiskR.Count >= 2) DrawChart(SparkDiskActivity, _cDiskR ?? _arrDiskR, GetSparkPen(_penDiskRead), SettingsService.Current.ChartShowFill, 0f, -1f, _cDiskW ?? _arrDiskW, GetSparkPen(_penDiskWrite)); } catch (Exception ex2) { AppLogger.Debug(ex2.Message); }
                try { if (_qNetDown.Count >= 2) DrawChart(SparkNetActivity, _cNetDown ?? _arrNetDown, GetSparkPen(_penNetDown), SettingsService.Current.ChartShowFill, 0f, -1f, _cNetUp ?? _arrNetUp, GetSparkPen(_penNetUp)); } catch (Exception ex2) { AppLogger.Debug(ex2.Message); }
                try { if (_qPing.Count >= 2) DrawChart(DashPingChart, _cPing ?? _arrPing, _penDashPingDynamic, SettingsService.Current.ChartShowFill, 0f, -1f); } catch (Exception ex2) { AppLogger.Debug(ex2.Message); }
            }, System.Windows.Threading.DispatcherPriority.Loaded);
        }

        // hide a badge's parent Border if the text is empty or "—"
        private void HideBadgeIfEmpty(string textBlockName)
        {
            if (FindName(textBlockName) is TextBlock tb)
            {
                bool empty = string.IsNullOrWhiteSpace(tb.Text) || tb.Text == "—";
                if (tb.Parent is Border badge)
                    badge.Visibility = empty ? Visibility.Collapsed : Visibility.Visible;
            }
        }

        /// <summary>
        /// Reads in the background what used to be read synchronously on the UI thread (4.5 s at start):
        /// the last Windows update, TPM, license, product key. The result goes into the same caches.
        /// </summary>
        private async Task CompleteDashboardSlowDataAsync()
        {
            var sw = System.Diagnostics.Stopwatch.StartNew();
            try
            {
                // While the background read runs, any other Populate (e.g. the one right after the window becomes visible) must
                // show "…" and NOT fall back to the synchronous WMI reads on the UI thread — that was the 3.5 s freeze at start
                // (Win32_QuickFixEngineering + Win32_Tpm + licence, read twice: once here in the background, once on the UI).
                _dashSlowInFlight = true;
                try { await PrefetchDashboardSlowDataAsync(); }
                finally { _dashSlowInFlight = false; }
                if (_summary != null) PopulateDashboardFromSummary(_summary);
                AppLogger.Info("Dashboard: slow data (license, TPM, updates) filled after {0} ms, in the background", sw.ElapsedMilliseconds);
            }
            catch (Exception ex) { AppLogger.Warning(ex, "CompleteDashboardSlowDataAsync"); }
        }

        private async Task PrefetchDashboardSlowDataAsync()
        {
            if (_cachedLastUpdateText != null && _cachedTpmText != null && _cachedLicenseText != null && _cachedWinProductKey != null) return;
            bool needUpd = _cachedLastUpdateText == null, needTpm = _cachedTpmText == null,
                 needLic = _cachedLicenseText == null, needKey = _cachedWinProductKey == null;
            var r = await Task.Run(() =>
            {
                string? upd = null, tpm = null, lic = null, key = null; bool tpm2 = false, licOk = false;
                if (needUpd)
                {
                    try
                    {
                        using var k = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\Results\Install");
                        if (k?.GetValue("LastSuccessTime") is string lastTime &&
                            DateTime.TryParse(lastTime, System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out var dt))
                            upd = SMDWin.Services.DateFormatHelper.FormatDate(dt);
                        else
                        {
                            DateTime? newest = null;
                            using var qfe = SMDWin.Services.WmiHelper.Searcher("SELECT InstalledOn FROM Win32_QuickFixEngineering", System.TimeSpan.FromSeconds(10));
                            using var res = qfe.Get();
                            foreach (System.Management.ManagementObject mo in res)
                                if (mo["InstalledOn"] is string s2 && DateTime.TryParse(s2, System.Globalization.CultureInfo.InvariantCulture, System.Globalization.DateTimeStyles.None, out var qd))
                                    if (newest == null || qd > newest) newest = qd;
                            upd = newest.HasValue ? SMDWin.Services.DateFormatHelper.FormatDate(newest.Value) : "—";
                        }
                    }
                    catch { upd = "—"; }
                }
                if (needTpm)
                {
                    try
                    {
                        using var searcher = SMDWin.Services.WmiHelper.Searcher(@"root\cimv2\security\microsofttpm", "SELECT SpecVersion FROM Win32_Tpm", System.TimeSpan.FromSeconds(10));
                        using var res = searcher.Get();
                        var obj = res.Cast<System.Management.ManagementObject>().FirstOrDefault();
                        if (obj?["SpecVersion"] is string specVer)
                        { string ver = specVer.Split(',')[0].Trim(); tpm = $"TPM {ver}"; tpm2 = ver.StartsWith("2"); }
                        else tpm = "";   // empty = "does not exist"; the translated text is set on the UI thread
                    }
                    catch { tpm = null; }
                }
                if (needLic)
                {
                    try
                    {
                        using var searcher = SMDWin.Services.WmiHelper.Searcher(
                            "SELECT LicenseStatus, LicenseFamily, Description FROM SoftwareLicensingProduct WHERE Name LIKE 'Windows%' AND PartialProductKey IS NOT NULL", System.TimeSpan.FromSeconds(10));
                        using var res = searcher.Get();
                        var obj = res.Cast<System.Management.ManagementObject>().FirstOrDefault();
                        if (obj != null)
                        {
                            uint status = obj["LicenseStatus"] is uint u ? u : 0;
                            string family = obj["LicenseFamily"]?.ToString() ?? "";
                            string desc = obj["Description"]?.ToString() ?? "";
                            string type = desc.Contains("OEM", StringComparison.OrdinalIgnoreCase) ? "OEM"
                                        : desc.Contains("Retail", StringComparison.OrdinalIgnoreCase) ? "Retail"
                                        : desc.Contains("Volume", StringComparison.OrdinalIgnoreCase) ? "Volume"
                                        : desc.Contains("MSDN", StringComparison.OrdinalIgnoreCase) ? "MSDN"
                                        : !string.IsNullOrEmpty(family) ? family : "Digital";
                            string statusStr = status == 1 ? T4("Licensed", "Licențiat", "Lizenziert", "Sous licence") : status == 5 ? T4("Notification", "Notificare", "Benachrichtigung", "Notification") : T4("Not activated", "Neactivat", "Nicht aktiviert", "Non activé");
                            lic = $"{statusStr} · {type}"; licOk = status == 1;
                        }
                        else lic = "—";
                    }
                    catch { lic = null; }
                }
                if (needKey)
                {
                    string k2 = "";
                    try
                    {
                        using var searcher = SMDWin.Services.WmiHelper.Searcher("SELECT OA3xOriginalProductKey FROM SoftwareLicensingService", System.TimeSpan.FromSeconds(10));
                        using var res = searcher.Get();
                        foreach (System.Management.ManagementObject mo in res) { k2 = mo["OA3xOriginalProductKey"]?.ToString()?.Trim() ?? ""; break; }
                    }
                    catch (Exception ex) { AppLogger.Debug($"OA3xProductKey: {ex.Message}"); }
                    if (string.IsNullOrWhiteSpace(k2))
                    {
                        try
                        {
                            using var rk = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\SoftwareProtectionPlatform", false);
                            k2 = rk?.GetValue("BackupProductKeyDefault")?.ToString()?.Trim() ?? "";
                        }
                        catch (Exception ex) { AppLogger.Debug($"BackupProductKey: {ex.Message}"); }
                    }
                    key = string.IsNullOrWhiteSpace(k2) ? "" : k2;
                }
                return (upd, tpm, tpm2, lic, licOk, key);
            });
            if (r.upd != null && _cachedLastUpdateText == null) _cachedLastUpdateText = r.upd;
            if (r.tpm != null && _cachedTpmText == null)
            {
                if (r.tpm.Length == 0) { _cachedTpmText = LanguageService.S("WindowsInfo", "NotPresent"); _cachedTpmBrush = _brGray as SolidColorBrush; }
                else { _cachedTpmText = r.tpm; _cachedTpmBrush = (r.tpm2 ? _brValue : _brGray) as SolidColorBrush; }
            }
            if (r.lic != null && _cachedLicenseText == null)
            {
                _cachedLicenseText = r.lic;
                _cachedLicenseBrush = (r.licOk ? _brValue : (r.lic == "—" ? _brGray : _brOrange)) as SolidColorBrush;
            }
            if (r.key != null && _cachedWinProductKey == null) _cachedWinProductKey = r.key;
            // what the background read could not get stays "—" (not null): a null would make the next Populate try the same slow
            // WMI query again, synchronously, on the UI thread
            if (needUpd) _cachedLastUpdateText ??= "—";
            if (needTpm && _cachedTpmText == null) { _cachedTpmText = "—"; _cachedTpmBrush = _brGray as SolidColorBrush; }
            if (needLic && _cachedLicenseText == null) { _cachedLicenseText = "—"; _cachedLicenseBrush ??= _brGray as SolidColorBrush; }
            if (needKey) _cachedWinProductKey ??= "";
        }

        private bool _dashSlowPending;   // true while the slow WMI data has not been read yet ("…" is shown)
        private bool _dashSlowInFlight;  // the background read of that data is running
        private bool DashSlowWaiting => _dashSlowPending || _dashSlowInFlight;
        private string? _cachedLastUpdateText;

        /// <summary>"Last update" on the Dashboard: over 60 days without updates → the "check" colour and the number of days in
        /// the tooltip (the same rule as in System Information, where the timeline shows "No update installed for N days").</summary>
        private static void MarkOldWindowsUpdate(TextBlock tb)
        {
            if (SMDWin.Services.DateFormatHelper.TryParseShown(tb.Text, out var d)
                && (DateTime.Today - d.Date).TotalDays > 60)
            {
                int days = (int)(DateTime.Today - d.Date).TotalDays;
                tb.SetResourceReference(TextBlock.ForegroundProperty, "StatusWarnBrush");
                tb.ToolTip = $"No Windows update for {days} days";
            }
            else
            {
                tb.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimaryBrush");
                tb.ToolTip = null;
            }
        }
        private string? _cachedTpmText;
        private SolidColorBrush? _cachedTpmBrush;
        private string? _cachedLicenseText;
        private SolidColorBrush? _cachedLicenseBrush;

        private void PopulateDashboardFromSummary(SystemSummary s)
        {
            SMDWin.Services.UiStallLogger.Mark("Populate:start");
            // Hide skeleton — real content is now loading
            if (DashboardSkeleton != null) DashboardSkeleton.Visibility = Visibility.Collapsed;

            if (TxtCpuModelHeader != null)
                TxtCpuModelHeader.Text = string.IsNullOrWhiteSpace(s.Cpu) ? "" : new DashTempConverter().Convert(s.Cpu, typeof(string), "cpu", System.Globalization.CultureInfo.InvariantCulture)?.ToString() ?? s.Cpu;
            if (FindName("TxtMemoryModelHeader") is TextBlock ramHdr) ramHdr.Text = "";
            if (TxtGpuModelHeader != null) TxtGpuModelHeader.Text = s.GpuName ?? "";

            // Force chart redraw after layout pass — fixes "frozen chart" bug when
            // ActualWidth was 0 at first draw (skeleton was covering the canvas)
            Dispatcher.InvokeAsync(() =>
            {
                _dashSizeChanged = true;
                try { if (_qCpuTemp.Count >= 2) DrawDashTempChart(DashCpuTempChart, _cCpuTemp ?? _arrCpuTemp, _penDashCpuTemp, SettingsService.Current.ChartShowFill); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                try { if (_qGpuTemp.Count >= 2) DrawDashTempChart(DashGpuTempChart, _cGpuTemp ?? _arrGpuTemp, _penDashGpuTemp, SettingsService.Current.ChartShowFill); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                try { if (_qDiskR.Count >= 2) DrawChart(SparkDiskActivity, _cDiskR ?? _arrDiskR, GetSparkPen(_penDiskRead), SettingsService.Current.ChartShowFill, 0f, -1f, _cDiskW ?? _arrDiskW, GetSparkPen(_penDiskWrite)); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                try { if (_qNetDown.Count >= 2) DrawChart(SparkNetActivity, _cNetDown ?? _arrNetDown, GetSparkPen(_penNetDown), SettingsService.Current.ChartShowFill, 0f, -1f, _cNetUp ?? _arrNetUp, GetSparkPen(_penNetUp)); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                try { if (_qPing.Count >= 2) DrawChart(DashPingChart, _cPing ?? _arrPing, _penDashPingDynamic, SettingsService.Current.ChartShowFill, 0f, -1f); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                // Sparklines
                try
                {
                    var gpuSparkColor = TryFindResource("GpuAccentBrush") is System.Windows.Media.SolidColorBrush gpuBr
                        ? gpuBr.Color : WpfColor.FromRgb(168, 85, 247);
                    // SparkGpu is handled by the smooth render tick — not redrawn twice
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }
                _dashSizeChanged = true;
            }, System.Windows.Threading.DispatcherPriority.Loaded);

            SMDWin.Services.UiStallLogger.Mark("Populate:texts");
            if (TxtOs            != null) TxtOs.Text            = s.OsName;
            if (TxtOsBuild       != null) TxtOsBuild.Text       = s.OsBuild;
            if (TxtUptime        != null) TxtUptime.Text        = s.Uptime;
            if (TxtDashArch      != null) TxtDashArch.Text      = s.Architecture;
            if (TxtMachine       != null) TxtMachine.Text       = FormatMachineName(s.Manufacturer, s.Model);
            if (TxtDashComputer  != null) TxtDashComputer.Text  = !string.IsNullOrEmpty(s.ComputerName) ? $"PC: {s.ComputerName}" : "";
            if (TxtDashBios != null)
            {
                // The SMBIOS version (more precise) is preferred over WMI
                string biosStr = _smbiosInfo?.BiosVersion is { Length: > 0 } bv ? bv : s.BiosVersion;
                string biosDate = _smbiosInfo?.BiosDate is { Length: > 0 } bd ? $" ({bd})" : "";
                TxtDashBios.Text = biosStr + biosDate;
            }
            if (TxtDashDisplay != null) TxtDashDisplay.Text = s.DisplayResolution.Length > 0 ? s.DisplayResolution : "—";
            // Add the board model from SMBIOS to TxtDashBiosV (if any)
            if (FindName("TxtDashBiosV") is System.Windows.Controls.TextBlock tbv && _smbiosInfo != null)
            {
                string board = !string.IsNullOrEmpty(_smbiosInfo.BoardProduct)
                    ? $"{_smbiosInfo.BoardManufacturer} {_smbiosInfo.BoardProduct}".Trim()
                    : "";
                if (!string.IsNullOrEmpty(board)) tbv.Text = board;
            }
            if (TxtDashDisplaySub!= null)
            {
                if (s.DisplayCount > 1)
                    TxtDashDisplaySub.Text = $"{s.DisplayCount} monitors";
                else
                    TxtDashDisplaySub.Text = string.IsNullOrEmpty(s.DisplayName) ? "" : s.DisplayName;
            }

            // Populate visible System panel in redesigned dashboard
            if (FindName("TxtOsV")          is TextBlock os2)  os2.Text  = s.OsName;
            if (FindName("TxtOsBuildV")     is TextBlock osb2)
            {
                string dispVer = s.OsBuild;
                if (string.IsNullOrWhiteSpace(dispVer))
                {
                    try
                    {
                        dispVer = Microsoft.Win32.Registry.GetValue(
                            @"HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows NT\CurrentVersion",
                            "DisplayVersion", null)?.ToString() ?? "";
                    }
                    catch { dispVer = ""; }
                }
                string buildNo = s.OsBuildNumber;    // "22621"
                osb2.Text = !string.IsNullOrWhiteSpace(dispVer) && !string.IsNullOrWhiteSpace(buildNo)
                    ? $"{dispVer} ({buildNo})"
                    : !string.IsNullOrWhiteSpace(buildNo) ? buildNo
                    : !string.IsNullOrWhiteSpace(dispVer) ? dispVer
                    : "—";
            }
            SMDWin.Services.UiStallLogger.Mark("Populate:uptime");
            // Uptime — from the summary or computed live from the boot time
            {
                string uptimeText = s.Uptime;
                if (string.IsNullOrWhiteSpace(uptimeText))
                {
                    // no WMI on the UI thread (at start the query could take seconds): the time since Windows started comes directly from the system
                    try
                    {
                        var up = SMDWin.Services.PowerOnClock.SinceOn;
                        uptimeText = SMDWin.Services.DisplayFormat.Uptime(up);
                    }
                    catch { uptimeText = "—"; }
                }
                SetUptimeCell(uptimeText);
                if (TxtUptime != null && string.IsNullOrWhiteSpace(TxtUptime.Text)) TxtUptime.Text = uptimeText;
                if (FindName("TxtDashWinUptime") is TextBlock wu)
                {
                    string osShort = (s.OsName ?? "").Replace("Microsoft ", "").Trim();
                    wu.Text = !string.IsNullOrWhiteSpace(osShort) ? osShort
                            : (string.IsNullOrEmpty(uptimeText) ? "" : $"uptime: {uptimeText}");
                }
            }
            if (FindName("TxtDashComputerV")is TextBlock pc2)  pc2.Text  = !string.IsNullOrWhiteSpace(s.ComputerName) ? s.ComputerName : System.Environment.MachineName;
            SMDWin.Services.UiStallLogger.Mark("Populate:header");
            // The Hardware card header shows the MACHINE (e.g. "Apple Inc. iMac14,2"), not the network name (DESKTOP-...).
            // The network name stays in the Windows card (PC NAME).
            if (FindName("TxtHardwareStripPcName") is TextBlock pcStrip)
            {
                string machine = FormatMachineName(s.Manufacturer, s.Model);
                pcStrip.Text = !string.IsNullOrWhiteSpace(machine) ? machine
                    : (!string.IsNullOrWhiteSpace(s.ComputerName) ? s.ComputerName : System.Environment.MachineName);
            }
            if (FindName("TxtDashComputerVSub") is TextBlock pcSub) pcSub.Text = s.ComputerName;
            // Hero bar right — computer name + OS line
            if (FindName("TxtDashComputerV_stub") is TextBlock pcStub) pcStub.Text = s.ComputerName;
            if (FindName("TxtHeroOsLine") is TextBlock heroOs) heroOs.Text = string.IsNullOrEmpty(s.OsName) ? "—" : s.OsName;
            if (FindName("TxtDashDisplayV") is TextBlock di2)  di2.Text  = s.DisplayResolution;
            if (FindName("TxtDashBiosV")    is TextBlock bi2)  bi2.Text  = !string.IsNullOrEmpty(s.BiosVersion) ? $"BIOS {s.BiosVersion}" : "";
            // BIOS: version + date combined in one label (e.g. "IM142.88Z.0118.B12  ·  08 Sept 2015")
            if (FindName("TxtDashBiosV2") is TextBlock bi3)
            {
                // Get BIOS version (strip "BIOS:" prefix if present)
                string biosVal = _smbiosInfo?.BiosVersion is { Length: > 0 } bvs
                    ? bvs : (s.BiosVersion ?? "");
                if (biosVal.StartsWith("BIOS:", StringComparison.OrdinalIgnoreCase))
                    biosVal = biosVal.Substring(5).Trim();
                // Strip existing parenthesized date from version string (we'll add it cleanly)
                biosVal = System.Text.RegularExpressions.Regex.Replace(biosVal, @"\s*\(\d{4}-\d{2}-\d{2}\)", "").Trim();

                // Get BIOS date
                string biosDateStr = _smbiosInfo?.BiosDate ?? "";
                if (string.IsNullOrEmpty(biosDateStr))
                {
                    string bvRaw = s.BiosVersion ?? "";
                    var mDate = System.Text.RegularExpressions.Regex.Match(bvRaw, @"\((\d{4}-\d{2}-\d{2})\)");
                    if (!mDate.Success) mDate = System.Text.RegularExpressions.Regex.Match(bvRaw, @"(\d{4}-\d{2}-\d{2})");
                    if (mDate.Success && DateTime.TryParse(mDate.Groups[1].Value, out var pd))
                        biosDateStr = SMDWin.Services.DateFormatHelper.FormatDate(pd);
                }

                string combined = biosVal;
                if (!string.IsNullOrEmpty(biosDateStr)) combined += $"  ·  {biosDateStr}";
                bi3.Text = !string.IsNullOrWhiteSpace(combined) ? combined : "—";

                // Footer BIOS field shows the same combined value (visible location)
                if (FindName("TxtDashBiosDateV") is TextBlock biosFooter)
                    biosFooter.Text = !string.IsNullOrWhiteSpace(combined) ? combined : "—";
            }

            if (FindName("TxtDashMoboV") is TextBlock mobo)
                mobo.Text = string.IsNullOrWhiteSpace(_boardNameResolved) ? "—" : _boardNameResolved;
            // CPU socket from SMBIOS
            if (FindName("TxtDashSocketV") is TextBlock sock)
                sock.Text = _smbiosInfo != null && !string.IsNullOrEmpty(_smbiosInfo.CpuSocket)
                    ? _smbiosInfo.CpuSocket : "—";
            // RAM slots: populate / total
            if (FindName("TxtDashRamSlotsV") is TextBlock slots)
                slots.Text = _smbiosInfo != null && _smbiosInfo.TotalSlots > 0
                    ? $"{_smbiosInfo.PopulatedSlots}/{_smbiosInfo.TotalSlots} slots"
                    : "—";
            // Install date Windows
            if (FindName("TxtDashInstallV") is TextBlock inst)
                inst.Text = !string.IsNullOrEmpty(s.InstallDate) ? s.InstallDate : "—";

            if (FindName("TxtDashSerialV") is TextBlock serial)
            {
                string sn = _smbiosInfo?.SystemSerial ?? "";
                // Filtreaza placeholdere comune (OEM pun "To Be Filled", "Default String" etc.)
                bool isFake = string.IsNullOrWhiteSpace(sn) ||
                    sn.Contains("To Be", StringComparison.OrdinalIgnoreCase) ||
                    sn.Contains("Default", StringComparison.OrdinalIgnoreCase) ||
                    sn.Contains("Not Applicable", StringComparison.OrdinalIgnoreCase) ||
                    sn == "0" || sn == "None";

                if (!isFake)
                {
                    serial.Text = sn;
                    if (FindName("TxtDashSerialLabel") is TextBlock lblReal)
                        lblReal.Text = LanguageService.S("Dashboard", "SerialNumber", "SERIAL NUMBER");
                }
                else
                {
                    string res = s.DisplayResolution ?? "";
                    string dispLabel = s.DisplayCount > 1
                        ? $"{s.DisplayCount} monitors"
                        : (s.DisplayName ?? "");
                    string dispVal = !string.IsNullOrWhiteSpace(dispLabel) && !string.IsNullOrWhiteSpace(res)
                        ? $"{dispLabel} · {res}"
                        : (!string.IsNullOrWhiteSpace(res) ? res : dispLabel);
                    bool hasDisplay = !string.IsNullOrWhiteSpace(dispVal);
                    serial.Text = hasDisplay ? dispVal : "—";
                    if (FindName("TxtDashSerialLabel") is TextBlock lblFallback)
                        lblFallback.Text = hasDisplay
                            ? LanguageService.S("Dashboard", "DisplayInfo", "DISPLAY")
                            : LanguageService.S("Dashboard", "SerialNumber", "SERIAL NUMBER");
                }
            }

            // BIOS Date — handled together with BIOS Version above in TxtDashBiosV2

            SMDWin.Services.UiStallLogger.Mark("Populate:updates-tpm-license");
            if (FindName("TxtDashLastUpdateV") is TextBlock lastUpd)
            {
                if (_cachedLastUpdateText != null)
                {
                    lastUpd.Text = _cachedLastUpdateText;
                }
                else if (DashSlowWaiting) { lastUpd.Text = "…"; }
                else
                try
                {
                    using var key = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(
                        @"SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\Results\Install");
                    if (key?.GetValue("LastSuccessTime") is string lastTime &&
                        DateTime.TryParse(lastTime, System.Globalization.CultureInfo.InvariantCulture,
                            System.Globalization.DateTimeStyles.None, out var dt))
                    {
                        lastUpd.Text = SMDWin.Services.DateFormatHelper.FormatDate(dt);
                    }
                    else
                    {
                        DateTime? newest = null;
                        using var qfeSearcher = SMDWin.Services.WmiHelper.Searcher(
                            "SELECT InstalledOn FROM Win32_QuickFixEngineering", System.TimeSpan.FromSeconds(10));
                        using (var __wmiTmp5 = qfeSearcher.Get())
                        {
                            foreach (System.Management.ManagementObject qfe in __wmiTmp5)
                        {
                            if (qfe["InstalledOn"] is string s2 &&
                                DateTime.TryParse(s2, System.Globalization.CultureInfo.InvariantCulture,
                                    System.Globalization.DateTimeStyles.None, out var qd))
                                if (newest == null || qd > newest) newest = qd;
                        }
                        }
                        lastUpd.Text = newest.HasValue ? SMDWin.Services.DateFormatHelper.FormatDate(newest.Value) : "—";
                    }
                    _cachedLastUpdateText = lastUpd.Text;
                }
                catch { lastUpd.Text = "—"; }
                MarkOldWindowsUpdate(lastUpd);
            }

            // Workgroup / Domain
            if (FindName("TxtDashWorkgroupV") is TextBlock wg)
            {
                try
                {
                    using var key = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(
                        @"SYSTEM\CurrentControlSet\Services\Tcpip\Parameters");
                    string domain = key?.GetValue("Domain") as string ?? "";
                    string workgroup = key?.GetValue("Workgroup") as string ?? "";
                    wg.Text = !string.IsNullOrWhiteSpace(domain) ? domain
                            : !string.IsNullOrWhiteSpace(workgroup) ? workgroup
                            : System.Net.NetworkInformation.IPGlobalProperties.GetIPGlobalProperties().DomainName is { Length: > 0 } dn ? dn
                            : "WORKGROUP";
                }
                catch { wg.Text = "—"; }
            }

            if (FindName("TxtDashTpmV") is TextBlock tpm)
            {
                if (_cachedTpmText != null)
                {
                    tpm.Text = _cachedTpmText;
                    tpm.Foreground = _cachedTpmBrush ?? _brGray;
                }
                else if (DashSlowWaiting) { tpm.Text = "…"; }
                else
                try
                {
                    using var searcher = SMDWin.Services.WmiHelper.Searcher(@"root\cimv2\security\microsofttpm",
                        "SELECT SpecVersion FROM Win32_Tpm", System.TimeSpan.FromSeconds(10));
                    using var __wmiTpmLic1 = searcher.Get();
                    var obj = __wmiTpmLic1.Cast<System.Management.ManagementObject>().FirstOrDefault();
                    if (obj?["SpecVersion"] is string specVer)
                    {
                        // SpecVersion = "1.2, ..." or "2.0, ..."
                        string ver = specVer.Split(',')[0].Trim();
                        tpm.Text = $"TPM {ver}";
                        tpm.Foreground = ver.StartsWith("2") ? _brValue : _brGray;
                    }
                    else { tpm.Text = LanguageService.S("WindowsInfo", "NotPresent"); tpm.Foreground = _brGray; }
                    _cachedTpmText = tpm.Text; _cachedTpmBrush = tpm.Foreground as SolidColorBrush;
                }
                catch { tpm.Text = "—"; }
            }

            // ── Boot mode: UEFI or MBR ──────────────────────────────────────
            if (FindName("TxtDashBootModeV") is TextBlock boot)
            {
                try
                {
                    // HKLM\SYSTEM\CurrentControlSet\Control — "PEFirmwareType" = 1=BIOS, 2=UEFI
                    var fwType = Microsoft.Win32.Registry.GetValue(
                        @"HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control",
                        "PEFirmwareType", null);
                    if (fwType is int fw)
                        { boot.Text = fw == 2 ? "UEFI" : "BIOS / MBR"; boot.Foreground = fw == 2 ? _brValue : _brOrange; }
                    else { boot.Text = LanguageService.S("WindowsInfo", "BootModeUefi"); boot.Foreground = _brValue; } // default on Win11
                }
                catch { boot.Text = "—"; }
            }

            // ── Secure Boot ──────────────────────────────────────────────────
            if (FindName("TxtDashSecureBootV") is TextBlock sb)
            {
                try
                {
                    bool enabled = SMDWin.Services.WindowsInfoReader.ReadSecureBoot();
                    sb.Text = enabled ? T4("Enabled ✓", "Activat ✓", "Aktiviert ✓", "Activé ✓") : T4("Disabled", "Dezactivat", "Deaktiviert", "Désactivé");
                    // Secure Boot off: a warning (orange), not an error; on: the normal text colour. A resource reference, so it follows
                    // the theme (the XAML default used to be the green "success" colour, which showed through as a green "Disabled")
                    sb.SetResourceReference(TextBlock.ForegroundProperty, enabled ? "TextPrimaryBrush" : "StatusWarnBrush");
                }
                catch { sb.Text = "—"; }
            }

            if (FindName("TxtDashLicenseV") is TextBlock lic)
            {
                if (_cachedLicenseText != null)
                {
                    lic.Text = _cachedLicenseText;
                    lic.Foreground = _cachedLicenseBrush ?? _brGray;
                }
                else if (DashSlowWaiting) { lic.Text = "…"; }
                else
                try
                {
                    using var searcher = SMDWin.Services.WmiHelper.Searcher(
                        "SELECT LicenseStatus, LicenseFamily, Description FROM SoftwareLicensingProduct " +
                        "WHERE Name LIKE 'Windows%' AND PartialProductKey IS NOT NULL", System.TimeSpan.FromSeconds(10));
                    using var __wmiTpmLic2 = searcher.Get();
                    var obj = __wmiTpmLic2.Cast<System.Management.ManagementObject>().FirstOrDefault();
                    if (obj != null)
                    {
                        uint status = obj["LicenseStatus"] is uint u ? u : 0;
                        string family = obj["LicenseFamily"]?.ToString() ?? "";
                        string desc   = obj["Description"]?.ToString()  ?? "";
                        string type   = desc.Contains("OEM",     StringComparison.OrdinalIgnoreCase) ? "OEM"
                                      : desc.Contains("Retail",  StringComparison.OrdinalIgnoreCase) ? "Retail"
                                      : desc.Contains("Volume",  StringComparison.OrdinalIgnoreCase) ? "Volume"
                                      : desc.Contains("MSDN",    StringComparison.OrdinalIgnoreCase) ? "MSDN"
                                      : !string.IsNullOrEmpty(family) ? family : "Digital";
                        string statusStr = status == 1 ? T4("Licensed", "Licențiat", "Lizenziert", "Sous licence") : status == 5 ? T4("Notification", "Notificare", "Benachrichtigung", "Notification") : T4("Not activated", "Neactivat", "Nicht aktiviert", "Non activé");
                        lic.Text = $"{statusStr} · {type}";
                        lic.Foreground = status == 1 ? _brValue : _brOrange;
                    }
                    else { lic.Text = "—"; }
                    _cachedLicenseText = lic.Text; _cachedLicenseBrush = lic.Foreground as SolidColorBrush;
                }
                catch { lic.Text = "—"; }
            }

            if (FindName("TxtDashSerialLastV") is TextBlock pk)
            {
                if (_cachedWinProductKey == null && DashSlowWaiting) { pk.Text = "…"; }
                else if (_cachedWinProductKey == null)
                {
                    string key = "";
                    try
                    {
                        using var searcher = SMDWin.Services.WmiHelper.Searcher(
                            "SELECT OA3xOriginalProductKey FROM SoftwareLicensingService", System.TimeSpan.FromSeconds(10));
                        using (var __wmiTmp6 = searcher.Get())
                        {
                            foreach (System.Management.ManagementObject mo in __wmiTmp6)
                        {
                            key = mo["OA3xOriginalProductKey"]?.ToString()?.Trim() ?? "";
                            break;
                        }
                        }
                    }
                    catch (Exception ex) { AppLogger.Debug($"OA3xProductKey: {ex.Message}"); }

                    if (string.IsNullOrWhiteSpace(key))
                    {
                        // Fallback: the backup key saved at install time (not present on every system)
                        try
                        {
                            using var rk = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(
                                @"SOFTWARE\Microsoft\Windows NT\CurrentVersion\SoftwareProtectionPlatform", false);
                            key = rk?.GetValue("BackupProductKeyDefault")?.ToString()?.Trim() ?? "";
                        }
                        catch (Exception ex) { AppLogger.Debug($"BackupProductKey: {ex.Message}"); }
                    }

                    // Cache an empty string too if nothing was found, so it is not retried on every tick
                    _cachedWinProductKey = string.IsNullOrWhiteSpace(key) ? "" : key;
                }

                if (_cachedWinProductKey != null)
                pk.Text = !string.IsNullOrWhiteSpace(_cachedWinProductKey)
                    ? MaskProductKeyForDashboard(_cachedWinProductKey)
                    : "Digital License"; // modern Windows 10/11 — the key is tied to a Microsoft account, not to a printed code
            }

            // hide the empty badges (the parent Border) so "—" does not appear
            HideBadgeIfEmpty("TxtDashCpuMaxMhz2");
            HideBadgeIfEmpty("TxtDashCpuCache2");
            HideBadgeIfEmpty("TxtDashSocketV");
            HideBadgeIfEmpty("TxtRamTypeLabel2");
            HideBadgeIfEmpty("TxtDashRamSlotsV");
            HideBadgeIfEmpty("TxtGpuVramSpec2");
            if (FindName("TxtMachineV")     is TextBlock mv)   mv.Text   = FormatMachineName(s.Manufacturer, s.Model);
            if (FindName("TxtDashArchV")    is TextBlock av)   av.Text   = s.Architecture;
            if (FindName("TxtDashDisplaySubV") is TextBlock dsv)
                dsv.Text = s.DisplayCount > 1 ? $"{s.DisplayCount} monitors" : s.DisplayName ?? "";
            // Hero bar right side - machine name
            if (TxtDashComputer != null && string.IsNullOrEmpty(TxtDashComputer.Text))
                TxtDashComputer.Text = s.ComputerName;
            // Windows card — crash count (if there is data from the session)
            if (FindName("TxtDashWinCrash") is TextBlock wc)
            {
                if (s.CrashCount > 0)
                { wc.Text = $"{s.CrashCount} crash{(s.CrashCount > 1 ? "es" : "")} {_LS("Crash", "DetectedSuffix")}"; wc.Foreground = _brOrange; }
                else
                { wc.Text = _LS("Crash", "NoRecentCrashes"); wc.Foreground = _brValue; }   // colour only when something is wrong
            }

            // Hardware strip row
            if (FindName("TxtCpuDashSpec2")  is TextBlock cs2)  cs2.Text  = s.Cpu;
            if (FindName("TxtDashCpuMaxMhz2")is TextBlock mhz2)
                mhz2.Text = s.CpuCores; // ex: "4 cores / 4 threads"
            if (FindName("TxtDashCpuCache2") is TextBlock cc2 && !string.IsNullOrEmpty(s.CpuCache))
                cc2.Text = s.CpuCache;  // e.g. "L3: 6 MB"  (from WMI, available)
            if (FindName("TxtGpuDash2")      is TextBlock gd2)  gd2.Text  = s.GpuName;
            if (FindName("TxtGpuVramSpec2")  is TextBlock gv2)  gv2.Text  = s.GpuVram;
            if (FindName("TxtRamDash2")      is TextBlock rd2)  rd2.Text  = s.TotalRam;
            if (FindName("TxtRamTypeLabel2") is TextBlock rt2)  rt2.Text  = s.RamType;
            if (FindName("TxtStorageDash2")  is TextBlock sd2)  sd2.Text  = TxtStorageDash?.Text  ?? "";
            if (FindName("TxtStorageSub2")   is TextBlock ss2)  ss2.Text  = TxtStorageSub?.Text   ?? "";
            // the right column of Hardware — live temps + VCore + Power from LHM
            try
            {
                if (FindName("TxtDashHwCpuTemp2") is TextBlock ct2)
                {
                    float ct = _lastTempSnap?.CpuTemp ?? -1f;
                    ct2.Text = ct > 0 ? $"{TempUnit.Fmt(ct)}" : "—";
                }
                if (FindName("TxtDashHwGpuTemp2") is TextBlock gt2)
                {
                    float gtp = _lastTempSnap?.GpuTemp ?? -1f;
                    gt2.Text = gtp > 0 ? $"{TempUnit.Fmt(gtp)}" : "—";
                }
                if (FindName("TxtDashVCore2") is TextBlock vc2)
                {
                    float vc = _lastTempSnap?.CpuVCoreV ?? -1f;
                    vc2.Text = vc > 0 ? $"{vc:F3} V" : "—";
                }
                if (FindName("TxtDashCpuPower2") is TextBlock pw2)
                {
                    float pw = _lastTempSnap?.CpuPowerW ?? -1f;
                    pw2.Text = pw > 0 ? $"{pw:F1} W" : "—";
                }
            }
            catch (Exception ex) { AppLogger.Debug("dash hw 2col: " + ex.Message); }
            if (TxtCpuDash       != null) TxtCpuDash.Text       = s.Cpu;
            if (TxtDashCpuLabelInline != null) TxtDashCpuLabelInline.Text = s.Cpu;
            if (TxtCpuDashSpec   != null) TxtCpuDashSpec.Text   = s.Cpu;
            if (TxtCpuCores      != null) TxtCpuCores.Text      = s.CpuCores;
            if (TxtCpuCache      != null) TxtCpuCache.Text      = s.CpuCache;
            if (TxtDashCpuMaxMhz != null) TxtDashCpuMaxMhz.Text = s.CpuMaxMHz.Length > 0 ? $"Max {s.CpuMaxMHz}" : "";
            if (TxtGpuDash       != null) TxtGpuDash.Text       = s.GpuName;
            if (TxtDashGpuLabelInline != null) TxtDashGpuLabelInline.Text = s.GpuName;
            if (TxtGpuVramSpec    != null) TxtGpuVramSpec.Text   = (s.GpuVram == "—" ? "" : s.GpuVram);
            if (TxtRamDash       != null) TxtRamDash.Text       = s.TotalRam;
            if (TxtRamTypeLabel  != null) TxtRamTypeLabel.Text  = s.RamType;

            // Network status — get all NICs once, reuse below for status dots
            System.Net.NetworkInformation.NetworkInterface[] _allNics = Array.Empty<System.Net.NetworkInformation.NetworkInterface>();
            try { _allNics = System.Net.NetworkInformation.NetworkInterface.GetAllNetworkInterfaces(); }
            catch (Exception ex) { AppLogger.Warning(ex, "PopulateDashboardFromSummary: GetAllNetworkInterfaces failed"); }

            if (TxtDashNetStatus != null || TxtDashNetIp != null)
            {
                try
                {
                    var activeNics = _allNics
                        .Where(n => n.OperationalStatus == System.Net.NetworkInformation.OperationalStatus.Up
                                 && n.NetworkInterfaceType != System.Net.NetworkInformation.NetworkInterfaceType.Loopback)
                        .ToList();
                    var active = activeNics.FirstOrDefault(n => n.GetIPProperties().GatewayAddresses.Count > 0) ?? activeNics.FirstOrDefault();
                    if (active != null)
                    {
                        if (TxtDashNetStatus != null)
                        {
                            TxtDashNetStatus.Text = LanguageService.S("Dashboard", "NetworkConnected");
                            TxtDashNetStatus.Foreground = _brGreen; // connected = green, fixed, regardless of the dynamic resource
                        }
                        var props = active.GetIPProperties();
                        var ip = props.UnicastAddresses
                            .FirstOrDefault(a => a.Address.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork)
                            ?.Address.ToString() ?? "";
                        if (TxtDashNetIp != null) TxtDashNetIp.Text = ip;
                        // Local IP, gateway, DNS in the Network card
                        if (FindName("TxtDashLocalIp") is TextBlock dli) dli.Text = ip;
                        if (FindName("TxtDashGatewayV") is TextBlock gw)
                        {
                            var gwAddr = props.GatewayAddresses
                                .FirstOrDefault(g => g.Address.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork)
                                ?.Address.ToString();
                            gw.Text = string.IsNullOrEmpty(gwAddr) ? "—" : gwAddr;
                        }
                        if (FindName("TxtDashDnsV") is TextBlock dns)
                        {
                            var dnsAddr = props.DnsAddresses
                                .FirstOrDefault(d => d.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork)
                                ?.ToString();
                            dns.Text = string.IsNullOrEmpty(dnsAddr) ? "—" : dnsAddr;
                        }
                    }
                    else
                    {
                        if (TxtDashNetStatus != null)
                        {
                            TxtDashNetStatus.Text = LanguageService.S("Dashboard", "NetworkDisconnected");
                            TxtDashNetStatus.Foreground = _brRed;
                        }
                        if (TxtDashNetIp    != null) TxtDashNetIp.Text    = "";
                        if (FindName("TxtDashLocalIp") is TextBlock dli2) dli2.Text = "—";
                        if (FindName("TxtDashGatewayV") is TextBlock gw2) gw2.Text = "—";
                        if (FindName("TxtDashDnsV") is TextBlock dns2) dns2.Text = "—";
                    }
                }
                catch (Exception ex)
                {
                    AppLogger.Warning(ex, "PopulateDashboardFromSummary: network status failed");
                    if (TxtDashNetStatus != null) TxtDashNetStatus.Text = "—";
                }
            }
            if (s.HasBattery)
            {
                if (TxtDashBatNetLabel != null) TxtDashBatNetLabel.Text = LanguageService.S("Dashboard", "LabelBatteryCaps");
                if (TxtDashBatNetMain  != null) TxtDashBatNetMain.Text  = s.BatteryCharge;
                if (TxtDashBatNetSub   != null) TxtDashBatNetSub.Text   = s.BatteryStatus;
                // Battery health — use the background-loaded _batteryWearPct directly
                if (TxtDashBatHealth != null)
                {
                    // _batteryWearPct is loaded in background on startup; -1 means not yet available
                    int health = _batteryWearPct >= 0 ? Math.Max(0, 100 - _batteryWearPct) : 0;
                    TxtDashBatHealth.Text = health > 0 ? $"{health}%" : "—";
                    // theme status colours (the fixed bright green had 2.3:1 contrast on Light)
                    // the brush itself, resolved now: this text sits in a hidden stub and the visible footer copies its Foreground
                    // through a binding — with a resource reference the footer kept the red of the first pass ("—" before the battery
                    // data arrived) and showed a 99 % battery in red.
                    string bk = health <= 0 ? "TextSecondaryBrush" : health >= 80 ? "StatusGoodBrush" : health >= 60 ? "StatusCheckBrush" : "StatusProblemBrush";
                    if (TryFindResource(bk) is Brush bb) TxtDashBatHealth.Foreground = bb;
                }
            }

            // ── Network device status dots — 3 states: Active / Inactive / Not Present ──
            // Green  = Active   (adapter present + valid IP + Up)
            // Orange = Inactive (adapter present but cable unplugged / Wi-Fi off / BT service stopped)
            // Grey   = Not Present (hardware absent)
            try
            {
                var nics = _allNics; // reuse cached from above — avoids double enumeration

                // ── LAN (Ethernet) ────────────────────────────────────────────────────
                var eth = nics.FirstOrDefault(n =>
                    n.NetworkInterfaceType == System.Net.NetworkInformation.NetworkInterfaceType.Ethernet &&
                    !n.Name.ToLower().Contains("bluetooth") &&
                    !n.Name.ToLower().Contains("virtual") &&
                    !n.Name.ToLower().Contains("vmware") &&
                    !n.Name.ToLower().Contains("vbox") &&
                    !n.Description.ToLower().Contains("virtual") &&
                    !n.Description.ToLower().Contains("hyper-v"));
                bool ethPresent = eth != null;
                bool ethHasIp   = ethPresent &&
                    eth!.OperationalStatus == System.Net.NetworkInformation.OperationalStatus.Up &&
                    eth.GetIPProperties().UnicastAddresses
                       .Any(a => a.Address.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork &&
                                 !System.Net.IPAddress.IsLoopback(a.Address));

                if (DotEthernet != null) DotEthernet.Fill = new SolidColorBrush(
                    ethHasIp   ? WpfColor.FromRgb(34,  197, 94)   // green — Active (cable + IP)
                  : ethPresent ? WpfColor.FromRgb(245, 158, 11)   // orange — Inactive (cable unplugged)
                  :              WpfColor.FromRgb(107, 114, 128)); // gri — Not Present
                if (ColEthernet != null) ColEthernet.Opacity = ethHasIp ? 1.0 : 0.55;
                bool ethNotUp = !ethHasIp;
                if (FindName("PnlEthernetFields") is FrameworkElement ethFields)
                    ethFields.Visibility = ethNotUp ? Visibility.Collapsed : Visibility.Visible;
                if (FindName("TxtDashEthNotConnected") is TextBlock ethNc)
                {
                    ethNc.Visibility = ethNotUp ? Visibility.Visible : Visibility.Collapsed;
                    ethNc.Text = ethPresent ? T4("Not connected", "Neconectat", "Nicht verbunden", "Non connecté") : T4("No adapter", "Fără adaptor", "Kein Adapter", "Aucun adaptateur");
                }
                if (TxtDashEthernetIp != null)
                {
                    if (ethHasIp)
                    {
                        var ip = eth!.GetIPProperties().UnicastAddresses
                            .FirstOrDefault(a => a.Address.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork &&
                                                 !System.Net.IPAddress.IsLoopback(a.Address))
                            ?.Address.ToString() ?? "";
                        TxtDashEthernetIp.Text = ip.Length > 0 ? ip : "active";
                    }
                    else
                        TxtDashEthernetIp.Text = ethPresent ? T4("disconnected", "deconectat", "getrennt", "déconnecté") : "—";
                }
                if (FindName("TxtDashEthernetName") is TextBlock ethName)
                    ethName.Text = eth != null ? eth.Name : "—";
                if (FindName("TxtDashEthernetSpeed") is TextBlock ethSpeed)
                    ethSpeed.Text = eth != null && ethHasIp
                        ? (eth.Speed >= 1_000_000_000 ? $"{eth.Speed/1_000_000_000} Gbps"
                           : eth.Speed >= 1_000_000   ? $"{eth.Speed/1_000_000} Mbps"
                           : "—")
                        : "—";
                if (FindName("TxtDashEthernetMac") is TextBlock ethMac)
                    ethMac.Text = eth != null ? BitConverter.ToString(eth.GetPhysicalAddress().GetAddressBytes()).Replace("-", ":") : "—";

                System.Net.NetworkInformation.NetworkInterface? wifi = null;
                System.Net.NetworkInformation.UnicastIPAddressInformation? wifiIpAddr = null;

                foreach (var nic in nics)
                {
                    if (nic.OperationalStatus != System.Net.NetworkInformation.OperationalStatus.Up) continue;
                    var nicName = nic.Name.ToLower();
                    var nicDesc = nic.Description.ToLower();
                    if (nicName.Contains("bluetooth") || nicDesc.Contains("bluetooth")) continue;
                    if (nic.NetworkInterfaceType == System.Net.NetworkInformation.NetworkInterfaceType.Loopback) continue;
                    if (nic.NetworkInterfaceType == System.Net.NetworkInformation.NetworkInterfaceType.Tunnel) continue;
                    // Skip pure Ethernet (no wifi/wireless in the description)
                    if (nic.NetworkInterfaceType == System.Net.NetworkInformation.NetworkInterfaceType.Ethernet
                        && !nicDesc.Contains("wi-fi") && !nicDesc.Contains("wifi") && !nicDesc.Contains("wireless")
                        && !nicName.Contains("wi-fi") && !nicName.Contains("wifi")) continue;
                    // Skip if it is the Ethernet already detected
                    if (eth != null && nic == eth) continue;

                    var ipv4 = nic.GetIPProperties().UnicastAddresses.FirstOrDefault(a =>
                        a.Address.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork &&
                        !System.Net.IPAddress.IsLoopback(a.Address) &&
                        !a.Address.ToString().StartsWith("169.254."));

                    bool isWifi = nic.NetworkInterfaceType == System.Net.NetworkInformation.NetworkInterfaceType.Wireless80211
                                  || nicName.Contains("wi-fi") || nicName.Contains("wifi") || nicName.Contains("wireless")
                                  || nicDesc.Contains("wi-fi") || nicDesc.Contains("wifi") || nicDesc.Contains("wireless");

                    if (ipv4 != null && (wifi == null || isWifi))
                    {
                        wifi = nic;
                        wifiIpAddr = ipv4;
                        if (isWifi) break;
                    }
                }

                if (wifi == null)
                {
                    wifi = nics.FirstOrDefault(nic =>
                    {
                        var nicName = nic.Name.ToLower();
                        var nicDesc = nic.Description.ToLower();
                        if (nicName.Contains("bluetooth") || nicDesc.Contains("bluetooth")) return false;
                        if (eth != null && nic == eth) return false;
                        return nic.NetworkInterfaceType == System.Net.NetworkInformation.NetworkInterfaceType.Wireless80211
                            || nicName.Contains("wi-fi") || nicName.Contains("wifi") || nicName.Contains("wireless")
                            || nicDesc.Contains("wi-fi") || nicDesc.Contains("wifi") || nicDesc.Contains("wireless");
                    });
                    // wifiIpAddr stays null — the adapter exists but has no valid active IP.
                }

                bool wifiPresent = wifi != null;
                bool wifiUp      = wifiPresent;
                bool wifiHasIp   = wifiIpAddr != null;
                bool wifiIsApipa = false;
                bool wifiActive  = wifiHasIp;

                                if (DotWifi != null) DotWifi.Fill = new SolidColorBrush(
                    wifiActive   ? WpfColor.FromRgb(34,  197, 94)
                  : wifiIsApipa  ? WpfColor.FromRgb(245, 158, 11)
                  : wifiUp       ? WpfColor.FromRgb(245, 158, 11)
                  : wifiPresent  ? WpfColor.FromRgb(107, 114, 128)
                  :                WpfColor.FromRgb(107, 114, 128));
                if (ColWifi != null) ColWifi.Opacity = wifiActive ? 1.0 : 0.55;
                if (TxtDashWifiSsid != null)
                {
                    if (wifiActive)
                        TxtDashWifiSsid.Text = wifiIpAddr!.Address.ToString();
                    else if (wifiIsApipa || wifiUp)
                        TxtDashWifiSsid.Text = "no internet";
                    else
                        TxtDashWifiSsid.Text = wifiPresent ? T4("disconnected", "deconectat", "getrennt", "déconnecté") : "—";
                }
                if (FindName("TxtDashWifiName") is TextBlock wifiNameTb)
                    wifiNameTb.Text = wifi != null ? wifi.Description : "—";
                if (FindName("TxtDashWifiIp") is TextBlock wifiIpTb)
                    wifiIpTb.Text = wifiActive ? wifiIpAddr!.Address.ToString() : "—";
                // Override TxtDashWifiSsid with the real SSID if it is wireless
                if (TxtDashWifiSsid != null && wifi != null)
                {
                    bool isRealWifi = wifi.NetworkInterfaceType == System.Net.NetworkInformation.NetworkInterfaceType.Wireless80211
                                      || wifi.Name.ToLower().Contains("wi-fi") || wifi.Name.ToLower().Contains("wifi");
                    if (isRealWifi)
                    {
                        // Incearca sa citeasca SSID-ul curent prin WlanApi
                        string ssid = "";
                        int sigPct = -1;
                        try { var wr = SMDWin.Services.WifiReader.Read(); ssid = wr.Ssid ?? ""; sigPct = wr.SignalPct; } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                        UpdateDashWifiBars(wifiActive && !string.IsNullOrEmpty(ssid) ? sigPct : -1);
                        TxtDashWifiSsid.Text = !string.IsNullOrEmpty(ssid) ? ssid
                            : wifiActive ? wifiIpAddr!.Address.ToString() : "not connected";
                    }
                }

                // ── Bluetooth ─────────────────────────────────────────────────────────
                bool btAdapterPresent = nics.Any(n =>
                    n.Name.ToLower().Contains("bluetooth") ||
                    n.Description.ToLower().Contains("bluetooth"));
                bool btServiceRunning = false;
                try
                {
                    var btSvc = new System.ServiceProcess.ServiceController("bthserv");
                    btServiceRunning = btSvc.Status == System.ServiceProcess.ServiceControllerStatus.Running;
                    if (!btAdapterPresent && btServiceRunning) btAdapterPresent = true;
                }
                catch (Exception ex) { AppLogger.Warning(ex, "Bluetooth service status check failed"); }

                if (DotBluetooth != null) DotBluetooth.Fill = new SolidColorBrush(
                    btServiceRunning  ? WpfColor.FromRgb(96,  165, 250)
                  : btAdapterPresent  ? WpfColor.FromRgb(245, 158, 11)
                  :                     WpfColor.FromRgb(107, 114, 128));
                if (ColBluetooth != null) ColBluetooth.Opacity = btServiceRunning ? 1.0 : 0.55;
                if (TxtDashBtDevices != null)
                    TxtDashBtDevices.Text = btServiceRunning ? "active"
                                          : btAdapterPresent ? "off"
                                          :                    "—";
                if (FindName("TxtDashBtName") is TextBlock btNameTb)
                {
                    var btNic = nics.FirstOrDefault(n =>
                        n.Name.ToLower().Contains("bluetooth") || n.Description.ToLower().Contains("bluetooth"));
                    btNameTb.Text = btNic != null ? btNic.Description : (btAdapterPresent ? "Bluetooth" : "—");
                }
                if (FindName("TxtDashBtVersion") is TextBlock btVerTb)
                {
                    string? btVer = GetBluetoothVersionViaApi();
                    btVerTb.Text = btVer ?? (btAdapterPresent ? "present" : "—");
                }
            }
            catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.unknown"); }

            if (!_hwConfigLogged && !string.IsNullOrWhiteSpace(s.Cpu))
            {
                _hwConfigLogged = true;
                AppLogger.LogSection("HARDWARE CONFIG",
                    ("Manufacturer",  s.Manufacturer),
                    ("Model",         s.Model),
                    ("CPU",           s.Cpu),
                    ("CPU Cores",     s.CpuCores),
                    ("CPU Cache",     s.CpuCache),
                    ("GPU",           s.GpuName),
                    ("GPU VRAM",      s.GpuVram),
                    ("RAM Total",     s.TotalRam),
                    ("RAM Type",      s.RamType),
                    ("Architecture",  s.Architecture),
                    ("Computer Name", s.ComputerName));
            }
        }

        private async Task PopulateDashStorageGridAsync()
        {
            if (DashStorageGrid == null) return;
            try
            {
                // ── Collect data from DriveInfo (a safe fallback, always available) ──────
                if (_allDisks.Count == 0)
                    try { _allDisks = await _hwService.GetDisksAsync(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }

                string FmtGB(double gb) => gb >= 900 ? $"{gb/1024.0:F1} TB" : $"{gb:F0} GB";
                string FmtGBf(double gb) => gb >= 900 ? $"{gb/1024.0:F1} TB" : $"{gb:F1} GB";

                var entries = new System.Collections.Generic.List<(
                    string DrivePath, string Label, string MediaType, string Model,
                    double TotalGB, double FreeGB, double UsedPct, string Health)>();

                // Fill from DriveInfo — always works
                foreach (var di in await SMDWin.Services.DriveSnapshot.ReadyDrivesAsync())
                {
                    try
                    {
                        if (di.Type == System.IO.DriveType.CDRom ||
                            di.Type == System.IO.DriveType.Ram  ||
                            di.Type == System.IO.DriveType.Unknown) continue;

                        double totalGB = di.TotalBytes / 1_073_741_824.0;
                        double freeGB  = di.FreeBytes / 1_073_741_824.0;
                        if (totalGB < 0.1) continue;
                        double usedPct = (totalGB - freeGB) / totalGB * 100.0;

                        string drivePath = di.Root.TrimEnd('\\');
                        string volLabel  = string.IsNullOrWhiteSpace(di.Label) ? "" : di.Label;
                        string label     = string.IsNullOrEmpty(volLabel) ? drivePath : $"{drivePath} — {volLabel}";

                        // Look up the model in _allDisks if available
                        string model = "—";
                        string mType = di.Type == System.IO.DriveType.Network ? "NET" : "";
                        foreach (var disk in _allDisks)
                        {
                            bool found = disk.Partitions.Any(p =>
                                p.Letter?.TrimEnd('\\').Equals(drivePath,
                                    StringComparison.OrdinalIgnoreCase) == true);
                            if (found)
                            {
                                model = disk.Model ?? "—";
                                if (string.IsNullOrEmpty(mType))
                                {
                                    bool isRemovableDash = false;
                                    try { isRemovableDash = di.Type == System.IO.DriveType.Removable; }
                                    catch (Exception ex) { AppLogger.Debug(ex.Message); }

                                    string mt = disk.MediaType ?? "";
                                    string mdl = disk.Model ?? "";
                                    if (isRemovableDash)
                                    {
                                        bool looksLikeStickDash = mdl.Contains("Flash Drive", StringComparison.OrdinalIgnoreCase)
                                            || mdl.Contains("Thumb", StringComparison.OrdinalIgnoreCase)
                                            || mdl.Contains("Kingston DataTraveler", StringComparison.OrdinalIgnoreCase)
                                            || mdl.Contains("SanDisk Cruzer", StringComparison.OrdinalIgnoreCase);
                                        bool externalLooksSsdDash = mt.Contains("SSD", StringComparison.OrdinalIgnoreCase)
                                            || mdl.Contains("SSD", StringComparison.OrdinalIgnoreCase);
                                        mType = looksLikeStickDash ? "USB Stick" : externalLooksSsdDash ? "SSD (external)" : "USB Drive (external)";
                                    }
                                    else
                                    {
                                        bool nvme = mt.Equals("NVMe", StringComparison.OrdinalIgnoreCase)
                                                 || mdl.Contains("NVMe", StringComparison.OrdinalIgnoreCase)
                                                 || mdl.Contains("M.2", StringComparison.OrdinalIgnoreCase);
                                        mType = nvme ? "SSD NVMe"
                                              : mt.Contains("SSD", StringComparison.OrdinalIgnoreCase) ? "SSD SATA"
                                              : mt.Equals("HDD", StringComparison.OrdinalIgnoreCase) ? "HDD SATA"
                                              : mdl.Contains("SSD", StringComparison.OrdinalIgnoreCase) ? "SSD SATA"
                                              : "Unknown type";
                                    }
                                }
                                break;
                            }
                        }
                        // Set the health from DiskHealthEntry.HealthPercent
                        string healthStr = "—";
                        var diskMatch = _allDisks.FirstOrDefault(d =>
                            d.Partitions.Any(p => p.Letter?.TrimEnd('\\')
                                .Equals(drivePath, StringComparison.OrdinalIgnoreCase) == true));
                        if (diskMatch != null && diskMatch.HealthPercent > 0)
                        {
                            healthStr = diskMatch.HealthPercent >= 80 ? "Good"
                                      : diskMatch.HealthPercent >= 50 ? "Fair"
                                      : "Poor";
                        }
                        else if (diskMatch?.Status is { Length: > 0 } st && st != "Unknown")
                            healthStr = st;
                        entries.Add((drivePath, label, mType, model, totalGB, freeGB, usedPct, healthStr));
                    }
                    catch (Exception ex) { AppLogger.Debug(ex.Message); }
                }

                // Totale
                double totalAll = entries.Sum(e => e.TotalGB);
                double freeAll  = entries.Sum(e => e.FreeGB);

                await Dispatcher.InvokeAsync(() =>
                {
                    if (DashStorageGrid == null) return;
                    DashStorageGrid.Children.Clear();
                    DashStorageGrid.RowDefinitions.Clear();

                    // Ascunde placeholder
                    if (FindName("TxtStorageDash2") is System.Windows.Controls.TextBlock ph)
                        ph.Visibility = entries.Count == 0
                            ? System.Windows.Visibility.Visible
                            : System.Windows.Visibility.Collapsed;

                    if (entries.Count == 0) return;

                    // Header: total used / total available
                    if (TxtDashStorageTotalFree != null)
                        TxtDashStorageTotalFree.Text = FmtGBf(freeAll); // the XAML already has the " free / " label next to it — not doubled here
                    if (FindName("TxtDashStorageTotalSize") is System.Windows.Controls.TextBlock stTotal)
                        stTotal.Text = FmtGBf(totalAll);
                    if (TxtDashStorageTotalSize != null)
                        TxtDashStorageTotalSize.Text = FmtGB(totalAll);

                    // Summary text
                    if (FindName("TxtDashStorageSummary2") is System.Windows.Controls.TextBlock ss2)
                        ss2.Text = string.Format(
                            entries.Count == 1 ? _LS("Storage", "PartitionsSummarySingularFmt") : _LS("Storage", "PartitionsSummaryPluralFmt"),
                            entries.Count, FmtGB(freeAll));

                    // ── compact list in the DETAILS column of the Storage row ──
                    // One disk → one row per partition: [C:] label · thin bar · "7 GB free".
                    // Several disks → one row per DISK (model · type, bar of total use, free), its partitions in the tooltip — the Storage
                    // row keeps the same height however many disks there are (at most 3 shown + "+N more").
                    // The bar is in the accent colour; yellow ≥ 90% used, red ≥ 95% (as on the Storage page).
                    var diskGroups = new System.Collections.Generic.Dictionary<string,
                        System.Collections.Generic.List<(string drivePath, string lbl, string mediaType,
                            string model, double totalGB, double freeGB, double usedPct, string health)>>();
                    foreach (var entry in entries)
                    {
                        string groupKey = !string.IsNullOrWhiteSpace(entry.Item4) && entry.Item4 != "—" ? entry.Item4 : entry.Item1;
                        if (!diskGroups.ContainsKey(groupKey)) diskGroups[groupKey] = new();
                        diskGroups[groupKey].Add(entry);
                    }

                    Brush Res(string key, Brush fb) => (TryFindResource(key) as Brush) ?? fb;
                    var accentBr = Res("DataBrush", System.Windows.Media.Brushes.CornflowerBlue);
                    var warnBr   = Res("StatusCheckBrush", new SolidColorBrush(WpfColor.FromRgb(245, 158, 11)));
                    var critBr   = Res("StatusProblemBrush", new SolidColorBrush(WpfColor.FromRgb(239, 68, 68)));
                    Brush BarBrush(double used) => used >= SMDWin.Services.StatusRules.DiskCritPct ? critBr : used >= SMDWin.Services.StatusRules.DiskWarnPct ? warnBr : accentBr;

                    // each partition = one block: the text row (letter + name | free) and below it a thin solid bar.
                    // Filled: accent (the system disk) / grey (the rest); yellow ≥ 90 %, red ≥ 95 %; empty: BorderBrush2.
                    System.Windows.Controls.Grid Line(string left, string leftSub, double usedPct, string right, string? tip, bool primary = true)
                    {
                        var g = new System.Windows.Controls.Grid { Margin = new System.Windows.Thickness(0, 0, 0, 9), Background = System.Windows.Media.Brushes.Transparent };
                        g.RowDefinitions.Add(new System.Windows.Controls.RowDefinition { Height = System.Windows.GridLength.Auto });
                        g.RowDefinitions.Add(new System.Windows.Controls.RowDefinition { Height = System.Windows.GridLength.Auto });
                        g.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = new System.Windows.GridLength(1, System.Windows.GridUnitType.Star) });
                        g.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = System.Windows.GridLength.Auto });
                        var name = new System.Windows.Controls.TextBlock
                        {
                            FontSize = Ui.FontM, VerticalAlignment = System.Windows.VerticalAlignment.Bottom,
                            TextTrimming = System.Windows.TextTrimming.CharacterEllipsis, Margin = new System.Windows.Thickness(0, 0, 10, 4),
                        };
                        name.Inlines.Add(new System.Windows.Documents.Run(left) { FontWeight = System.Windows.FontWeights.SemiBold });
                        if (!string.IsNullOrEmpty(leftSub))
                        {
                            var sub = new System.Windows.Documents.Run("  " + leftSub);
                            sub.SetResourceReference(System.Windows.Documents.TextElement.ForegroundProperty, "TextSecondaryBrush");
                            name.Inlines.Add(sub);
                        }
                        name.SetResourceReference(System.Windows.Controls.TextBlock.ForegroundProperty, "TextPrimaryBrush");
                        g.Children.Add(name);

                        var free = new System.Windows.Controls.TextBlock
                        {
                            Text = right, FontSize = Ui.FontM, FontWeight = System.Windows.FontWeights.SemiBold,
                            HorizontalAlignment = System.Windows.HorizontalAlignment.Right, VerticalAlignment = System.Windows.VerticalAlignment.Bottom,
                            Margin = new System.Windows.Thickness(0, 0, 0, 4),
                        };
                        if (usedPct >= SMDWin.Services.StatusRules.DiskWarnPct) free.Foreground = BarBrush(usedPct);
                        else free.SetResourceReference(System.Windows.Controls.TextBlock.ForegroundProperty, "TextPrimaryBrush");
                        System.Windows.Controls.Grid.SetColumn(free, 1);
                        g.Children.Add(free);

                        if (usedPct > 0 || !string.IsNullOrEmpty(right))
                        {
                            // a thin solid bar with rounded ends (as in Windows Settings › Storage), not a row of blocks
                            double f = Math.Clamp(usedPct / 100.0, 0, 1);
                            var bar = new System.Windows.Controls.Grid { Height = 6, ClipToBounds = true };
                            bar.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = new System.Windows.GridLength(f, System.Windows.GridUnitType.Star) });
                            bar.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = new System.Windows.GridLength(1 - f, System.Windows.GridUnitType.Star) });
                            var track = new System.Windows.Controls.Border { CornerRadius = new System.Windows.CornerRadius(3) };
                            track.SetResourceReference(System.Windows.Controls.Border.BackgroundProperty, "BorderBrush2");
                            System.Windows.Controls.Grid.SetColumnSpan(track, 2);
                            bar.Children.Add(track);
                            if (f > 0)
                            {
                                var fill = new System.Windows.Controls.Border { CornerRadius = new System.Windows.CornerRadius(3), MinWidth = 6 };
                                if (usedPct >= SMDWin.Services.StatusRules.DiskWarnPct || primary) fill.Background = BarBrush(usedPct);
                                else { fill.SetResourceReference(System.Windows.Controls.Border.BackgroundProperty, "TextSecondaryBrush"); fill.Opacity = 0.55; }
                                bar.Children.Add(fill);
                            }
                            System.Windows.Controls.Grid.SetRow(bar, 1);
                            System.Windows.Controls.Grid.SetColumnSpan(bar, 2);
                            g.Children.Add(bar);
                        }
                        if (!string.IsNullOrEmpty(tip)) g.ToolTip = tip;
                        return g;
                    }
                    void AddLine(System.Windows.Controls.Grid line)
                    {
                        DashStorageGrid.RowDefinitions.Add(new System.Windows.Controls.RowDefinition { Height = System.Windows.GridLength.Auto });
                        System.Windows.Controls.Grid.SetRow(line, DashStorageGrid.RowDefinitions.Count - 1);
                        DashStorageGrid.Children.Add(line);
                    }
                    // the same formatting as Storage and System Info (DisplayFormat.SizeGb)
                    string FreeStr(double gb) { string s = SMDWin.Services.DisplayFormat.SizeGb(gb); return T4($"{s} free", $"{s} liberi", $"{s} frei", $"{s.Replace("GB", "Go").Replace("TB", "To")} libres"); }
                    // "2.7 GB free of 118 GB" — the size of the whole partition next to the free space, as in Windows Settings
                    string FreeOfStr(double gb, double tot)
                    {
                        string f = SMDWin.Services.DisplayFormat.SizeGb(gb), t = SMDWin.Services.DisplayFormat.SizeGb(tot);
                        return T4($"{f} free of {t}", $"{f} liberi din {t}", $"{f} von {t} frei",
                                  $"{f.Replace("GB", "Go").Replace("TB", "To")} libres sur {t.Replace("GB", "Go").Replace("TB", "To")}");
                    }

                    var groupsOrdered = diskGroups.Values
                        .OrderByDescending(g => g.Any(e => e.drivePath.Equals("C:", StringComparison.OrdinalIgnoreCase)))
                        .ToList();
                    const int MaxLines = 3;
                    if (groupsOrdered.Count == 1)
                    {
                        var parts = groupsOrdered[0];
                        foreach (var e in parts.Take(MaxLines))
                        {
                            string vol = e.lbl.Contains('—') ? e.lbl[(e.lbl.IndexOf('—') + 1)..].Trim() : "";
                            // no volume label → the name Windows gives too (as on the Storage page), the capacity is in the tooltip
                            if (string.IsNullOrEmpty(vol)) vol = T4("Local Disk", "Disc local", "Lokaler Datenträger", "Disque local");
                            bool isSys = e.drivePath.Equals("C:", StringComparison.OrdinalIgnoreCase);
                            AddLine(Line(e.drivePath, vol, e.usedPct, FreeOfStr(e.freeGB, e.totalGB),
                                $"{e.lbl}\n{SMDWin.Services.DisplayFormat.SizeGb(e.totalGB)} · {e.usedPct:F0}% used", isSys));
                        }
                        if (parts.Count > MaxLines)
                            AddLine(Line($"+{parts.Count - MaxLines} more", "", 0, "", null));
                    }
                    else
                    {
                        foreach (var grp in groupsOrdered.Take(MaxLines))
                        {
                            double tot = grp.Sum(e => e.totalGB), fr = grp.Sum(e => e.freeGB);
                            double used = tot > 0 ? (tot - fr) / tot * 100.0 : 0;
                            string letters = string.Join(" ", grp.Select(e => e.drivePath));
                            string mdl = grp[0].model is { Length: > 0 } m && m != "—" ? m : grp[0].drivePath;
                            bool grpSys = grp.Any(e => e.drivePath.Equals("C:", StringComparison.OrdinalIgnoreCase));
                            // the disk type (USB Stick / SATA HDD / SSD…) before the model, when known
                            string mt = grp[0].mediaType;
                            string subTxt = !string.IsNullOrWhiteSpace(mt) && mt != "Unknown type" && !grpSys ? $"{mt} · {mdl}" : mdl;
                            string tipTxt = mdl + " · " + grp[0].mediaType + "\n" + string.Join("\n",
                                grp.Select(e => $"{e.lbl}: {FreeStr(e.freeGB)} of {e.totalGB:F0} GB ({e.usedPct:F0}% used)"));
                            AddLine(Line(letters, subTxt, Math.Max(used, grp.Max(e => e.usedPct) >= SMDWin.Services.StatusRules.DiskWarnPct ? grp.Max(e => e.usedPct) : used),
                                FreeOfStr(fr, tot), tipTxt, grpSys));
                        }
                        if (groupsOrdered.Count > MaxLines)
                            AddLine(Line($"+{groupsOrdered.Count - MaxLines} more drives", "", 0, "", null));
                    }

                    // The name in the COMPONENT column (the full model, not cut at 14 characters) + health in STATUS
                    var mainGrp = groupsOrdered[0];
                    string mainModel = mainGrp[0].model is { Length: > 0 } mm && mm != "—" ? mm : mainGrp[0].drivePath;
                    if (FindName("TxtDashRowDiskName") is System.Windows.Controls.TextBlock rowName)
                    {
                        rowName.Text = groupsOrdered.Count > 1 ? $"{mainModel}  +{groupsOrdered.Count - 1}" : mainModel;
                        rowName.ToolTip = string.Join("\n", groupsOrdered.Select(g => g[0].model + " · " + g[0].mediaType));
                    }
                    if (FindName("TxtDashRowDiskCaption") is System.Windows.Controls.TextBlock rowCap)
                        rowCap.Text = groupsOrdered.Count > 1 ? $"STORAGE · {groupsOrdered.Count} DRIVES" : "STORAGE";
                    // used space shows in the partition bars; the dial shows disk activity (UpdateDashCardsLive).
                    // Critical space on the main disk → the same discreet glow as for hot CPU / GPU.
                    {
                        double mTot = mainGrp.Sum(e => e.totalGB), mFree = mainGrp.Sum(e => e.freeGB);
                        double mUsed = mTot > 0 ? (mTot - mFree) / mTot * 100.0 : -1;
                        SetCardGlow(FindName("DashDiskRow") as System.Windows.Controls.Border, mUsed >= 95 ? "StatusCritBrush" : null);
                    }
                    if (FindName("TxtDashRowDiskHealth") is System.Windows.Controls.TextBlock rowHealth)
                    {
                        // the health of the drive named on the card (the system drive). It used to be the weakest of all drives, so the
                        // card of a Samsung SSD showed the 82 % of the second drive (an HDD). The other drives are listed in the tooltip.
                        var withHealth = _allDisks.Where(d => d.HealthPercent > 0).ToList();
                        var mainDisk = withHealth.FirstOrDefault(d => string.Equals(d.Model?.Trim(), mainGrp[0].model?.Trim(), StringComparison.OrdinalIgnoreCase))
                                       ?? withHealth.OrderBy(d => d.DiskIndex).FirstOrDefault();
                        var healths = mainDisk != null ? new List<int> { mainDisk.HealthPercent } : new List<int>();
                        rowHealth.ToolTip = withHealth.Count > 1
                            ? string.Join("\n", withHealth.Select(d => $"{d.Model?.Trim()}: {d.HealthPercent}%"))
                            : null;
                        if (healths.Count > 0)
                        {
                            int worst = healths.Min();
                            // the cell is already labelled "Health": only the figure, in the theme's status colour
                            rowHealth.Text = $"{worst}%";
                            // the mark (bound to Tag) carries the state colour; the word stays neutral when all is well
                            if (worst >= 80)
                            {
                                rowHealth.SetResourceReference(FrameworkElement.TagProperty, "StatusOkBrush");
                                rowHealth.SetResourceReference(System.Windows.Controls.TextBlock.ForegroundProperty, "TextPrimaryBrush");
                            }
                            else { rowHealth.Foreground = worst >= 50 ? warnBr : critBr; rowHealth.Tag = rowHealth.Foreground; }
                        }
                        else
                        {
                            string h = mainGrp[0].health ?? "—";
                            rowHealth.Text = h;
                            rowHealth.Foreground = h is "Good" or "OK" or "Healthy" ? (Brush)Res("StatusGoodBrush", System.Windows.Media.Brushes.Green)
                                                 : h == "—" ? (Brush)Res("TextSecondaryBrush", System.Windows.Media.Brushes.Gray) : warnBr;
                        }
                    }

}, System.Windows.Threading.DispatcherPriority.Loaded);
            }
            catch (Exception ex)
            {
                AppLogger.Warning(ex, "PopulateDashStorageGridAsync failed");
            }
        }

        /// <summary>
        /// Draws a donut chart in the DashStorageDonut canvas.
        /// Each partition = a coloured arc; free space = semi-transparent grey.
        /// </summary>
        private void DrawStorageDonut(
            System.Collections.Generic.List<(string label, double totalGB, double usedGB, System.Windows.Media.Color color)> entries)
        {
            var canvas = FindName("DashStorageDonut") as System.Windows.Controls.Canvas;
            if (canvas == null) return;
            canvas.Children.Clear();

            double canvasW = canvas.ActualWidth  > 4 ? canvas.ActualWidth  : 120;
            double canvasH = canvas.ActualHeight > 4 ? canvas.ActualHeight : 60;
            double size    = Math.Min(canvasH, canvasW);
            double cx      = canvasW / 2;
            double cy      = canvasH / 2;
            double rOuter  = size / 2 - 2;
            double rInner  = rOuter * 0.50;

            if (entries.Count == 0 || rOuter < 4) return;

            double totalAll = entries.Sum(e => e.totalGB);
            if (totalAll < 0.01) return;

            double startAngle = -Math.PI / 2;

            System.Windows.Point Pt(double r, double angle) =>
                new(cx + r * Math.Cos(angle), cy + r * Math.Sin(angle));

            var palette = new[]
            {
                System.Windows.Media.Color.FromRgb(59, 130, 246),   // blue - partition 1
                System.Windows.Media.Color.FromRgb(34, 197,  94),   // green - partition 2
                System.Windows.Media.Color.FromRgb(245, 158, 11),   // yellow - partition 3
                System.Windows.Media.Color.FromRgb(168,  85, 247),  // violet - partition 4
                System.Windows.Media.Color.FromRgb(239,  68, 68),   // red - partition 5
            };

            void AddArc(double r1, double r2, double a1, double a2,
                        System.Windows.Media.Brush fill)
            {
                if (Math.Abs(a2 - a1) < 0.005) return;
                bool large = (a2 - a1) > Math.PI;

                var geom = new StreamGeometry();
                using (var ctx = geom.Open())
                {
                    var p1o = Pt(r1, a1); var p2o = Pt(r1, a2);
                    var p1i = Pt(r2, a2); var p2i = Pt(r2, a1);
                    ctx.BeginFigure(p1o, true, true);
                    ctx.ArcTo(p2o, new System.Windows.Size(r1, r1), 0, large, System.Windows.Media.SweepDirection.Clockwise, true, false);
                    ctx.LineTo(p1i, true, false);
                    ctx.ArcTo(p2i, new System.Windows.Size(r2, r2), 0, large, System.Windows.Media.SweepDirection.Counterclockwise, true, false);
                }
                geom.Freeze();
                var path = new System.Windows.Shapes.Path
                    { Data = geom, Fill = fill, IsHitTestVisible = false };
                canvas.Children.Add(path);
            }

            for (int i = 0; i < entries.Count; i++)
            {
                var (label, totalGB, usedGB, _) = entries[i];
                double sweep = 2 * Math.PI * (totalGB / totalAll);
                var col = palette[i % palette.Length];
                double usedPctPart = totalGB > 0 ? (usedGB / totalGB) * 100 : 0;
                var dynCol = usedPctPart >= SMDWin.Services.StatusRules.DiskCritPct
                    ? System.Windows.Media.Color.FromRgb(239, 68, 68)
                    : usedPctPart >= SMDWin.Services.StatusRules.DiskWarnPct
                    ? System.Windows.Media.Color.FromRgb(245, 158, 11)
                    : col;
                var solidBr  = new System.Windows.Media.SolidColorBrush(dynCol);
                var fadedBr  = new System.Windows.Media.SolidColorBrush(
                    System.Windows.Media.Color.FromArgb(40, dynCol.R, dynCol.G, dynCol.B));
                solidBr.Freeze(); fadedBr.Freeze();

                double usedSweep = totalGB > 0 ? sweep * Math.Clamp(usedGB / totalGB, 0, 1) : 0;
                double freeSweep = sweep - usedSweep;
                const double gap = 0.0;

                // Arc utilizat
                if (usedSweep > gap * 2)
                    AddArc(rOuter, rInner, startAngle, startAngle + usedSweep - gap, solidBr);
                // Arc liber
                if (freeSweep > gap * 2)
                    AddArc(rOuter, rInner, startAngle + usedSweep, startAngle + sweep - gap, fadedBr);

                startAngle += sweep;
            }

            // Text central: % total utilizat
            double totalUsed = entries.Sum(e => e.usedGB);
            double totalPct  = totalAll > 0 ? totalUsed / totalAll * 100 : 0;
            var tb = new System.Windows.Controls.TextBlock
            {
                Text = $"{totalPct:F0}%",
                FontSize = Ui.FontS, FontWeight = System.Windows.FontWeights.Bold,
                Foreground = (System.Windows.Media.Brush)(TryFindResource("TextPrimaryBrush")
                             ?? System.Windows.Media.Brushes.White),
            };
            tb.Measure(new System.Windows.Size(double.PositiveInfinity, double.PositiveInfinity));
            System.Windows.Controls.Canvas.SetLeft(tb, cx - tb.DesiredSize.Width / 2);
            System.Windows.Controls.Canvas.SetTop( tb, cy - tb.DesiredSize.Height / 2);
            canvas.Children.Add(tb);
        }


        private async Task PopulateNetCardAsync()
        {
            try
            {
                // If battery present — card stays as Battery; add network as subtitle
                // If no battery (desktop) — card shows Network info
                bool hasBat = _summary?.BatteryCharge != null
                    && _summary.BatteryCharge != "—"
                    && _summary.BatteryCharge != "N/A";

                var adapters = await _netService.GetAdaptersAsync();
                var active = adapters
                    .Where(a => a.Status == "Up" && !string.IsNullOrEmpty(a.IpAddress)
                                && !a.IpAddress.StartsWith("169.254"))
                    .ToList();

                if (hasBat)
                {
                    // Battery card — show only battery info, no network tags
                    if (TxtDashBatNetLabel != null) TxtDashBatNetLabel.Text = LanguageService.S("Dashboard", "LabelBattery");
                }
                else
                {
                    // Desktop / no battery — show network
                    if (TxtDashBatNetLabel != null) TxtDashBatNetLabel.Text = LanguageService.S("Dashboard", "LabelNetwork");

                    if (active.Count == 0)
                    {
                        if (TxtDashBatNetMain != null) TxtDashBatNetMain.Text = "—";
                        if (TxtDashBatNetSub  != null) TxtDashBatNetSub.Text  = "No active connection";
                        return;
                    }

                    var primary = active.First();
                    if (TxtDashBatNetMain != null)
                    {
                        TxtDashBatNetMain.Text = primary.IpAddress;
                        TxtDashBatNetMain.SetResourceReference(TextBlock.ForegroundProperty, "TextPrimaryBrush");
                    }

                    var badges = active.Take(3).Select(a =>
                    {
                        string n = a.Name.ToLower();
                        if (n.Contains("wi-fi") || n.Contains("wifi") || n.Contains("wireless")) return "Wi-Fi";
                        if (n.Contains("bluetooth")) return "BT";
                        return "LAN";
                    });
                    if (TxtDashBatNetSub != null)
                        TxtDashBatNetSub.Text = string.Join("", badges.Distinct());
                }
            }
            catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.PopulateNetCardAsync"); }
        }

        // ── Top processes for the "System at a glance" cards ──────────────
        private bool _glanceBusy = false;
        private DateTime _lastGlanceRefresh = DateTime.MinValue;
        private async System.Threading.Tasks.Task RefreshGlanceProcessesAsync()
        {
            if (_glanceBusy) return;
            if ((DateTime.Now - _lastGlanceRefresh).TotalSeconds < 2.5) return;  // debounce
            _glanceBusy = true;
            try
            {
                var snap = await _procMonitor.GetSnapshotAsync(5, light: true);
                _lastGlanceRefresh = DateTime.Now;
                if (snap == null) return;
                var topCpu = snap.TopByCpu != null && snap.TopByCpu.Count > 0 ? snap.TopByCpu[0] : null;
                var topRam = snap.TopByRam != null && snap.TopByRam.Count > 0 ? snap.TopByRam[0] : null;
                UpdateDashTopProcesses(snap);   // the "Activity" row on the dashboard (MainWindow.DashRows.cs)
                if (topCpu != null)
                {
                    if (FindName("TxtGlanceTopCpu") is System.Windows.Controls.TextBlock tc) tc.Text = topCpu.Name;
                    if (FindName("TxtGlanceTopCpuPct") is System.Windows.Controls.TextBlock tcp) tcp.Text = $"{topCpu.CpuPct:F1}% CPU";
                }
                if (topRam != null)
                {
                    if (FindName("TxtGlanceTopRam") is System.Windows.Controls.TextBlock tr) tr.Text = topRam.Name;
                    if (FindName("TxtGlanceTopRamMB") is System.Windows.Controls.TextBlock trm)
                        trm.Text = topRam.RamMB >= 1024 ? $"{topRam.RamMB/1024:F2} GB" : $"{topRam.RamMB:F0} MB";
                }
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }
            finally { _glanceBusy = false; }
        }
    }
